class Solution {
public:
    int smallestChair(vector<vector<int>>& times, int targetFriend) {
        int n = times.size();
        vector<int> idx(n);
        for (int i = 0; i < n; i++) idx[i] = i;
        sort(idx.begin(), idx.end(), [&](int a, int b) {
            return times[a][0] < times[b][0];
        });

        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> occupied;
        priority_queue<int, vector<int>, greater<int>> available;
        int nextChair = 0;

        for (int i : idx) {
            int arr = times[i][0], leave = times[i][1];
            while (!occupied.empty() && occupied.top().first <= arr) {
                available.push(occupied.top().second);
                occupied.pop();
            }
            int chair;
            if (!available.empty()) {
                chair = available.top();
                available.pop();
            } else {
                chair = nextChair++;
            }
            occupied.push({leave, chair});
            if (i == targetFriend) return chair;
        }
        return -1;
    }
};
